const deadline = Date.now() + 170000;
async function killCollect(pattern) {
  const npc = sdk.findNearbyNpc(pattern, { reachable: true });
  if (!npc) return 'notfound';
  const r = await bot.attack(npc);
  if (!r.success) return 'fail ' + r.message;
  await sdk.waitForCondition(() => !sdk.getState().player.inCombat, 25000).catch(() => 'timeout');
  await bot.dismissBlockingUI();
  // pick up coin drops
  const s = sdk.getState();
  const coins = sdk.findGroundItem(/coins/i);
  if (coins) { const pr = await bot.pickupItem(coins); return 'killed, pickup ' + pr.success; }
  return 'killed';
}
const res = [];
for (let i = 0; i < 4; i++) {
  if (Date.now() > deadline) break;
  res.push(await killCollect(/goblin/i));
}
const inv = sdk.getState().inventory || [];
return { res, pos: [sdk.getState().player.worldX, sdk.getState().player.worldZ] };

