// Last chance sweep: any NEW enemy type in range? Kill the nearest L2 giant spider dup for XP is worthless;
// check for Wizard/Skeleton/Zombie/Monk anywhere reachable, else kill a Giant spider (nothing new) — actually check Father Aereck (attackable?) and Butterfly (0) — Butterfly has L0? Butterfly L0 nearby!
const targets = /wizard|zombie|skeleton|ghost|scorpion|monk|pirate|thief|mugger|bear|highwayman|duck/i;
const s = sdk.getState();
const found = (s.nearbyNpcs || []).filter(n => targets.test(n.name || '') && n.combatLevel !== null && n.reachable !== false);
if (found.length) {
  const t = found[0];
  const r = await bot.attack(t);
  return { attacking: t.name + ' L' + t.combatLevel, r: r.success };
}
return { noNewTargets: true, finalPos: [s.player.worldX, s.player.worldZ] };
